\title{The Type-Channel Law:\\ How Much a Splitting Type Reveals About the Residue Class of a Prime}
\author{Aristotle (Harmonic)}
\date{September 29, 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $f\in\mathbb{Z}[x]$ be separable of degree $n$ with Galois group $G\le S_n$. By Chebotarev's density theorem the Frobenius element of a random unramified prime is uniformly distributed on $G$, and its cycle type is the splitting type $T$ of $f$ modulo $p$. By class field theory the coset $c$ of the Frobenius modulo the derived subgroup $G'$ is determined by $p$ modulo the conductor of the maximal abelian subfield. The \emph{type channel} is the mutual information $I(c;T)$ for $g$ uniform on $G$. We prove a consolidated law:
(i) $I(c;T)=H(T)-H(T\mid c)=\lb[G:G']-H(c\mid T)$, with $I=H(T)$ for abelian $G$ and $I=0$ for perfect $G$;
(ii) the sandwich $\max(0,H(T)-\lb|G'|)\le I(c;T)\le\min(H(T),\lb[G:G'])$;
(iii) universality under injective homomorphisms respecting derived subgroups and type partitions, covering conjugate and cross-degree realisations;
(iv) a battery calculus: chain rule, monotonicity, ceiling and saturation;
(v) exact degree-six channels: $\tfrac43+\tfrac14\lb 3$ bits for $x^6-2$ (group $D_6$), with the degree-$\le4$ type encoding under-reporting by exactly $\tfrac13$ bit, and one bit for $S_3$ acting regularly (Galois closure of $x^3-2$).
We also show that the informal statement ``$I$ equals the expected entropy of the abelianization class given the type'' is false ($S_3$ is a counterexample), and that super-additivity of batteries fails for every nontrivial abelianization. All closed forms are confirmed numerically on the primes below $60\,000$.
\end{abstract}

\section{Introduction}

A polynomial $f\in\mathbb{Z}[x]$ that is irreducible over $\mathbb{Q}$ usually factors modulo primes. The pattern of factor degrees, the \emph{splitting type}, is governed by the Galois group $G$ of $f$. For $p\nmid\disc(f)$ the Frobenius class $\Frob_p\subset G$ has cycle type equal to the splitting type, and $\Frob_p$ is equidistributed in $G$ (Chebotarev). The image of $\Frob_p$ in $G^{\mathrm{ab}}=G/G'$ depends only on $p$ modulo the conductor $m$ of the maximal abelian subextension (class field theory).

This raises a quantitative question with a cryptographic flavour: \emph{how many bits about $p\bmod m$ does the factorization pattern of $f\bmod p$ reveal?} The question arose in an extended experimental programme on type channels in degrees two to six, on joint readouts (``batteries''), and on the universality of channel values across fields with the same group. This paper consolidates the programme into a single set of statements with proofs, corrects one informal claim, and extends the exact computations to degree six.

The arithmetic enters only through the dictionary
\[
p \text{ random} \;\longleftrightarrow\; g\in G \text{ uniform},\qquad
\text{splitting type} \;\longleftrightarrow\; \text{cycle type of } g,\qquad
p\bmod m \;\longleftrightarrow\; gG'.
\]
Every theorem below is a statement about finite groups with the uniform measure.

\section{Setting and definitions}

\subsection{Finite Shannon calculus}
Let $S$ be a finite nonempty set with the uniform measure. A \emph{readout} is a function $f:S\to A$. Write $S_a=f^{-1}(a)$ and $p_f(a)=|S_a|/|S|$.

\begin{definition}
$H(f)=-\sum_{a\in f(S)}p_f(a)\lb p_f(a)$, $I(f;g)=H(f)+H(g)-H(f,g)$ and $H(f\mid g)=H(f,g)-H(g)$, where $(f,g)$ is the pair readout. The conditional mutual information is
$I(f;g\mid t)=\sum_{b\in t(S)}p_t(b)\,I_{S_b}(f;g)$, computed on each fibre of $t$ with its own uniform measure.
\end{definition}

\begin{lemma}[Gibbs]
$I(f;g)\ge0$, hence $I(f;g\mid t)\ge0$.
\end{lemma}

\begin{lemma}[Data processing]
For any map $\varphi$, $H(\varphi\circ f)\le H(f)$.
\end{lemma}
\begin{proof}[Proof sketch]
$H(\varphi\circ f)\le H(\varphi\circ f,f)$, and $(\varphi\circ f,f)$ is an injective relabelling of $f$ via $a\mapsto(\varphi(a),a)$.
\end{proof}

\begin{corollary}[Ceiling]
$H(\mathrm{id}_S)=\lb|S|$, hence $H(f)\le\lb|S|$ for every readout $f$.
\end{corollary}

\begin{lemma}[Transport]
If $e:S\to S'$ is injective then $H_{e(S)}(f)=H_S(f\circ e)$ and $I_{e(S)}(f;g)=I_S(f\circ e;g\circ e)$.
\end{lemma}

\begin{lemma}[Partition invariance]
If $f(a)=f(b)\iff f'(a)=f'(b)$ for all $a,b\in S$, then $I(f;g)=I(f';g)$ for every $g$.
\end{lemma}

\begin{lemma}[Chain rule]
$H(X,t)=H(t)+\sum_{b\in t(S)}p_t(b)\,H_{S_b}(X)$.
\end{lemma}
\begin{proof}[Proof sketch]
Factor $p_{(X,t)}(a,b)=p_t(b)\,p_{X\mid S_b}(a)$, expand the logarithm, and sum over $a$ first.
\end{proof}

\subsection{The group setting}
Let $S$ be a finite subgroup of a group $\Gamma$ and let $N\subseteq S$ be a subgroup.

\begin{definition}[Coset readout]
$c:\Gamma\to K$ is a \emph{coset readout} for $N$ in $S$ if $c(a)=c(b)\iff a^{-1}b\in N$ for $a,b\in S$. Write $k=|c(S)|=[S:N]$.
\end{definition}

\begin{definition}[Derived subgroup]
$N$ is the \emph{derived subgroup} of $S$ if it is the smallest subgroup containing all commutators $aba^{-1}b^{-1}$ with $a,b\in S$.
\end{definition}

\begin{definition}[Type channel, loss, completeness]
A \emph{splitting-type readout} $T$ is any readout on $S$ (canonically, the cycle type for $S\le S_n$). The \emph{type channel} is $I(c;T)$. Its \emph{loss} is $\lb k-I(c;T)$. The readout $T$ is \emph{complete} if $T(a)=T(b)\Rightarrow c(a)=c(b)$ for $a,b\in S$.
\end{definition}

\begin{definition}[Faithful sextic type]
For $g\in S_6$, $\tau_6(g)=(\#\text{fixed points},\#\text{points on 2-cycles},\#\text{points on 3-cycles})$. This separates all eleven cycle types of $S_6$. The \emph{quartic record} $\tau_4(g)=(\#\text{fixed points},\#\text{points on 2-cycles})$ is faithful only in degree $\le4$.
\end{definition}

\section{Coset readouts}

\begin{lemma}[Lagrange in bits]\label{lem:lagrange}
Every fibre of a coset readout has size $|N|$, so $H(c)=\lb k$ and $\lb|S|=\lb k+\lb|N|$.
\end{lemma}

\begin{lemma}[Completeness criterion]\label{lem:complete}
$I(c;T)=\lb k$ if and only if $T$ is complete, i.e.\ $H(c\mid T)=0$.
\end{lemma}
\begin{proof}
$I(c;T)=H(c)-H(c\mid T)=\lb k-H(c\mid T)$, and $H(c\mid T)=0$ exactly when $c$ is constant on each fibre of $T$.
\end{proof}

\section{The unified type-channel law}

\begin{theorem}[Unified Type-Channel Law]\label{thm:law}
Let $S$ be a finite group with derived subgroup $N$, let $c$ be a coset readout for $N$, and let $T$ be any readout. Then
\begin{enumerate}
\item $I(c;T)=H(T)-H(T\mid c)$;
\item $I(c;T)=\lb[S:N]-H(c\mid T)$;
\item if $S$ is abelian, then $I(c;T)=H(T)$;
\item if $N=S$ (i.e.\ $S$ is perfect), then $I(c;T)=0$.
\end{enumerate}
\end{theorem}
\begin{proof}[Proof sketch]
(1) is the definition rearranged. (2) is $I=H(c)-H(c\mid T)$ together with Lemma~\ref{lem:lagrange}. (3) If $S$ is abelian then $N=\{1\}$ and $c$ is injective on $S$, so $H(T\mid c)=0$. (4) If $N=S$ then $c$ is constant, so $0\le I\le H(c)=0$.
\end{proof}

\begin{proposition}[Counterexample to the informal wording]
For $S_3$ realised by $x^3+x+1$ with the cycle-type readout, $I(c;T)=1$ but $H(c\mid T)=0$.
\end{proposition}
\begin{proof}
$S_3'=A_3$. The types $1^3$ and $3$ are even and $1\,2$ is odd, so $T$ is complete and Lemma~\ref{lem:complete} gives $I=1$.
\end{proof}

\begin{proposition}
If $T$ is complete and $[S:N]\ge2$, then $I(c;T)\neq H(c\mid T)$.
\end{proposition}
\begin{proof}
$H(c\mid T)=0$, while $I(c;T)=\lb[S:N]>0$.
\end{proof}

\begin{remark}
The informal statement ``$I$ is exactly $\mathbb{E}[H(G^{\mathrm{ab}}\text{-class}\mid T)]$'' must be read as ``$\mathbb{E}[H(G^{\mathrm{ab}}\text{-class}\mid T)]$ is the \emph{loss} $\lb[G:G']-I$'', which is exactly Theorem~\ref{thm:law}(2).
\end{remark}

\section{The sandwich}

\begin{theorem}[Residual type uncertainty]\label{thm:resid}
$H(T\mid c)\le\lb|N|$.
\end{theorem}
\begin{proof}[Proof sketch]
$H(c,T)\le\lb|S|=\lb k+\lb|N|$ and $H(c)=\lb k$.
\end{proof}

\begin{theorem}[Sandwich Theorem]\label{thm:sandwich}
\[
\max\bigl(0,\;H(T)-\lb|N|\bigr)\;\le\;I(c;T)\;\le\;\min\bigl(H(T),\;\lb[S:N]\bigr).
\]
Equivalently, the type deficit $H(T)-I(c;T)$ is at most $\lb|G'|$.
\end{theorem}
\begin{proof}[Proof sketch]
The lower bound combines Gibbs' inequality with Theorem~\ref{thm:law}(1) and Theorem~\ref{thm:resid}. The upper bound uses $I\le H(T)$ and $I\le H(c)=\lb k$.
\end{proof}

\begin{example}[$x^4-2$: the lower bound is non-vacuous]
Let $D_4$ act on the roots $\alpha i^j$ ($j\in\mathbb{Z}/4$) by $j\mapsto\pm j+a$. The cycle types are $1^4$ (once), $4$ (twice, the quarter-turns), $2^2$ (three times: the half-turn and the reflections $j\mapsto1-j,\ 3-j$) and $1^2\,2$ (twice: $j\mapsto -j,\ 2-j$). So $H(T)=\tfrac52-\tfrac38\lb3\approx1.906$. The derived subgroup is the centre, of order $2$, so from the type statistics alone
\[
I(c;T)\ \ge\ \tfrac32-\tfrac38\lb3\ \approx\ 0.906\ >\ \tfrac34 .
\]
The exact value is $I(c;T)=\tfrac94-\tfrac38\lb3\approx1.656$. The loss $\tfrac38\lb3-\tfrac14=\tfrac38\,h(\tfrac13)$ comes entirely from the type $2^2$, which is split $1:2$ between two cosets ($h$ denotes the binary entropy).
\end{example}

\section{Universality}

\begin{theorem}[Universality]\label{thm:univ}
Let $e:\Gamma\to\Gamma'$ be a homomorphism that is injective on $S$, and put $S'=e(S)$, $N'=e(N)$. Let $c$ and $c'$ be coset readouts for $N\subseteq S$ and $N'\subseteq S'$, and let $T,T'$ satisfy $T(a)=T(b)\iff T'(e(a))=T'(e(b))$ for $a,b\in S$. Then $I_{S'}(c';T')=I_S(c;T)$.
\end{theorem}
\begin{proof}[Proof sketch]
By transport, $I_{S'}(c';T')=I_S(c'\circ e;T'\circ e)$. Since $e(a)^{-1}e(b)=e(a^{-1}b)\in e(N)$ iff $a^{-1}b\in N$, the readouts $c'\circ e$ and $c$ induce the coset partition of $S$. By hypothesis $T'\circ e$ and $T$ induce the same partition. Apply partition invariance in both arguments.
\end{proof}

\begin{corollary}[Conjugate realisations]
For $S,N\le S_n$ and $h\in S_n$, the conjugates $hSh^{-1}$ and $hNh^{-1}$, with any coset readout, have the same cycle-type channel as $S$ and $N$.
\end{corollary}

\begin{example}
Conjugating $D_4$ by $(1\,2)$ gives a different subgroup of $S_4$ (the stabiliser of $\{\{0,1\},\{2,3\}\}$) with channel exactly $\tfrac94-\tfrac38\lb3$.
\end{example}

\begin{example}[Cross-degree universality]
$S_3$ acting regularly on the six conjugates of a primitive element of $\mathbb{Q}(\sqrt[3]{2},\omega)$ has types $1^6,3^2,2^3$ with frequencies $1,2,3$. Hence $H(T)=\tfrac23+\tfrac12\lb3$ and $I(c;T)=1$, identical to the cubic realisation $x^3+x+1$.
\end{example}

\section{Batteries}

\begin{theorem}[Battery Chain Rule]
$I(c;(T_1,T_2))=I(c;T_1)+I(c;T_2\mid T_1)$ and $I(c;T_2\mid T_1)\ge0$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply the chain rule, conditioning on $T_1$, to $H(T_1,T_2)$, $H(c,T_1,T_2)$ and $H(c,T_1)$, and subtract. Nonnegativity is Gibbs' inequality on each fibre.
\end{proof}

\begin{theorem}[Monotone and capped]
$I(c;T_1)\le I(c;(T_1,T_2))\le\lb[S:N]$.
\end{theorem}

\begin{theorem}[Saturation]
If $T_1$ is complete, then $I(c;T_2\mid T_1)=0$ and $I(c;(T_1,T_2))=\lb[S:N]$.
\end{theorem}
\begin{proof}[Proof sketch]
$I(c;T_1)=\lb k$ is already the ceiling, and the chain rule together with nonnegativity forces the conditional term to vanish.
\end{proof}

\begin{theorem}[Super-additivity is not universal]
If $[S:N]\ge2$ then $I(c;(c,c))<I(c;c)+I(c;c)$.
\end{theorem}
\begin{proof}
$I(c;c)=\lb k>0$, while $I(c;(c,c))\le\lb k<2\lb k$.
\end{proof}

\begin{example}
For $S_4$ ($x^4+x+1$) the battery (cycle type, image of the first root) carries exactly $1$ bit, and the second dial adds nothing. For $D_4$ ($x^4-2$), $I(c;T)\approx1.656$ and $I(c;\text{root})=1$, while the battery reaches $2$ bits, with $I(c;\text{root}\mid T)=\tfrac38\lb3-\tfrac14$.
\end{example}

\section{Degree six}

The roots of $x^6-2$ are $\alpha\zeta^j$ ($\zeta=e^{2\pi i/6}$, $j\in\mathbb{Z}/6$). The group $D_6$ (order $12$) acts by $j\mapsto j+a$ and $j\mapsto a-j$. Its derived subgroup is $C_3=\{j\mapsto j+2t\}$, and $D_6/C_3\cong C_2\times C_2$ is read by (parity of translation, orientation), i.e.\ by $p\bmod24$ via $\mathbb{Q}(\sqrt{-3},\sqrt2)$.

\begin{center}
\begin{tabular}{lcccc}
\toprule
elements & type & $\tau_6$ & $\tau_4$ & count\\
\midrule
identity & $1^6$ & $(6,0,0)$ & $(6,0)$ & 1\\
$j\mapsto j\pm1$ & $6$ & $(0,0,0)$ & $(0,0)$ & 2\\
$j\mapsto j\pm2$ & $3^2$ & $(0,0,6)$ & $(0,0)$ & 2\\
$j\mapsto j+3$ & $2^3$ & $(0,6,0)$ & $(0,6)$ & 1\\
$j\mapsto a-j$, $a$ odd & $2^3$ & $(0,6,0)$ & $(0,6)$ & 3\\
$j\mapsto a-j$, $a$ even & $1^22^2$ & $(2,4,0)$ & $(2,4)$ & 3\\
\bottomrule
\end{tabular}
\end{center}

\begin{proposition}
$\tau_4(j\mapsto j+1)=\tau_4(j\mapsto j+2)$ but $\tau_6(j\mapsto j+1)\ne\tau_6(j\mapsto j+2)$.
\end{proposition}

\begin{theorem}[$D_6$ channel]
With $L=\lb3$ and the faithful readout: $H(T)=1+\tfrac34L$, $H(c)=2$, $H(c,T)=\tfrac53+\tfrac12L$, so
\[
I(c;T)=\tfrac43+\tfrac14L\approx1.7296,\qquad \text{loss}=\tfrac23-\tfrac14L=\tfrac13\,h(\tfrac14)\approx0.2704>0 .
\]
\end{theorem}
\begin{proof}[Proof sketch]
Type counts $(1,2,2,4,3)$ out of $12$. The joint counts are $(1,2,2,1,3,3)$: the type $2^3$ splits as $1$ (half-turn) $+\,3$ (odd reflections) between two cosets, and every other type lies in a single coset. The loss is positive iff $\lb3<\tfrac83$.
\end{proof}

\begin{theorem}[Cost of the unfaithful record]
$I(c;\tau_4)=1+\tfrac14L$, hence $I(c;\tau_6)-I(c;\tau_4)=\tfrac13$ bit exactly.
\end{theorem}
\begin{proof}[Proof sketch]
$\tau_4$ merges the types $6$ and $3^2$, each of probability $\tfrac16$, lowering $H(T)$ by $\tfrac13h(\tfrac12)=\tfrac13$. They lie in different cosets, so $H(c,T)$ is unchanged.
\end{proof}

\begin{theorem}[Regular $S_3$]
For $S_3$ acting regularly on six points, with $N=C_3$: $H(\tau_6)=\tfrac23+\tfrac12\lb3$ and $I(c;\tau_6)=1$.
\end{theorem}

\section{Algorithms}

\paragraph{Algorithm A (exact channel).} Enumerate $G$ from generators by breadth-first closure. Compute $G'$ as the closure of all commutators. Label the cosets $gG'$, tabulate the counts of $T$, $c$ and $(c,T)$, and return $I=H(c)+H(T)-H(c,T)$ together with the loss and the sandwich bounds. The cost is $O(|G|^2n)$.

\paragraph{Algorithm B (empirical channel).} For each prime $p\le X$ with $p\nmid2\disc(f)$, compute the splitting type by distinct-degree factorisation: iterate $h\leftarrow h^p\bmod f$ and peel off $\gcd(h-x,f)$. Tabulate $(r(p),\text{type})$ for a residue map $r$ and return the plug-in mutual information.

