"""Exact type channel of a permutation group: law, sandwich and battery decomposition."""
from __future__ import annotations

import math
from collections import Counter
from typing import Callable, Dict, Hashable, List, Sequence, Tuple

Perm = Tuple[int, ...]


def compose(a: Perm, b: Perm) -> Perm:
    return tuple(a[b[x]] for x in range(len(a)))


def inverse(a: Perm) -> Perm:
    r = [0] * len(a)
    for i, v in enumerate(a):
        r[v] = i
    return tuple(r)


def generate(gens: Sequence[Perm]) -> List[Perm]:
    ident: Perm = tuple(range(len(gens[0])))
    seen, frontier = {ident}, [ident]
    while frontier:
        nxt: List[Perm] = []
        for g in frontier:
            for s in gens:
                h = compose(s, g)
                if h not in seen:
                    seen.add(h)
                    nxt.append(h)
        frontier = nxt
    return sorted(seen)


def cycle_type(g: Perm) -> Tuple[int, ...]:
    seen, out = set(), []
    for x in range(len(g)):
        if x not in seen:
            m, y = 0, x
            while y not in seen:
                seen.add(y); y = g[y]; m += 1
            out.append(m)
    return tuple(sorted(out, reverse=True))


def entropy(labels: Sequence[Hashable]) -> float:
    n = len(labels)
    return -sum(c / n * math.log2(c / n) for c in Counter(labels).values())


def type_channel(gens: Sequence[Perm],
                 T: Callable[[Perm], Hashable] = cycle_type,
                 T2: Callable[[Perm], Hashable] | None = None) -> Dict[str, float]:
    G = generate(gens)                                                   # step 1
    comm = {compose(compose(a, b), compose(inverse(a), inverse(b))) for a in G for b in G}
    N = generate(sorted(comm))                                           # step 2: G'
    lab: Dict[Perm, int] = {}
    k = 0
    for g in G:                                                          # step 3: cosets
        if g not in lab:
            for h in N:
                lab[compose(g, h)] = k
            k += 1
    c = [lab[g] for g in G]
    t = [T(g) for g in G]
    HT, Hc, HcT = entropy(t), entropy(c), entropy(list(zip(c, t)))       # step 4
    I = Hc + HT - HcT
    out = {"order": len(G), "derived": len(N), "index": k, "H(T)": HT, "I": I,
           "H(T|c)": HcT - Hc, "loss H(c|T)": HcT - HT, "ceiling": math.log2(k),
           "lower": max(0.0, HT - math.log2(len(N))), "upper": min(HT, math.log2(k))}
    if T2 is not None:                                                   # step 5: battery
        t2 = [T2(g) for g in G]
        pair = list(zip(t, t2))
        Ipair = Hc + entropy(pair) - entropy(list(zip(c, pair)))
        out["I battery"] = Ipair
        out["I(c;T2|T)"] = Ipair - I                                     # chain rule
    return out


if __name__ == "__main__":
    D4 = [tuple((u * k + a) % 4 for k in range(4)) for u in (1, 3) for a in range(4)]
    r = type_channel(D4, T2=lambda g: g[0])
    for key, val in r.items():
        print(f"{key:>14}: {val:.6f}" if isinstance(val, float) else f"{key:>14}: {val}")
    L = math.log2(3)
    assert abs(r["I"] - (9 / 4 - 3 * L / 8)) < 1e-12
    assert abs(r["I battery"] - 2) < 1e-12

"""Empirical type channel from real primes via distinct-degree factorisation."""
from __future__ import annotations

import math
from collections import Counter
from typing import Callable, Hashable, List, Sequence, Tuple

Poly = List[int]  # coefficients, lowest degree first


def trim(a: Poly) -> Poly:
    while a and a[-1] == 0:
        a.pop()
    return a


def pmod(a: Poly, m: Poly, p: int) -> Poly:
    a = trim([x % p for x in a])
    inv = pow(m[-1], p - 2, p)
    while len(a) >= len(m):
        q, sh = a[-1] * inv % p, len(a) - len(m)
        for i, mi in enumerate(m):
            a[sh + i] = (a[sh + i] - q * mi) % p
        trim(a)
    return a


def pmul(a: Poly, b: Poly, m: Poly, p: int) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            out[i + j] += x * y
    return pmod(out, m, p)


def ppow(b: Poly, e: int, m: Poly, p: int) -> Poly:
    r: Poly = [1]
    b = pmod(b, m, p)
    while e:
        if e & 1:
            r = pmul(r, b, m, p)
        b = pmul(b, b, m, p)
        e >>= 1
    return r


def pgcd(a: Poly, b: Poly, p: int) -> Poly:
    a, b = trim([x % p for x in a]), trim([x % p for x in b])
    while b:
        a, b = b, pmod(a, b, p)
    inv = pow(a[-1], p - 2, p)
    return [x * inv % p for x in a]


def pdiv(a: Poly, b: Poly, p: int) -> Poly:
    a = trim([x % p for x in a])
    inv = pow(b[-1], p - 2, p)
    q = [0] * max(1, len(a) - len(b) + 1)
    while len(a) >= len(b):
        c, sh = a[-1] * inv % p, len(a) - len(b)
        q[sh] = c
        for i, bi in enumerate(b):
            a[sh + i] = (a[sh + i] - c * bi) % p
        trim(a)
    return trim(q)


def splitting_type(f: Poly, p: int) -> Tuple[int, ...]:
    f = trim([x % p for x in f])
    degs: List[int] = []
    h: Poly = [0, 1]
    d = 0
    while len(f) > 1:
        d += 1
        if 2 * d > len(f) - 1:          # what is left is irreducible
            degs.append(len(f) - 1)
            break
        h = ppow(h, p, f, p)            # h = x^(p^d) mod f
        diff = h + [0] * max(0, 2 - len(h))
        diff[1] = (diff[1] - 1) % p
        trim(diff)
        g = pgcd(f, diff, p) if diff else f
        k = (len(g) - 1) // d           # number of degree-d factors
        degs += [d] * k
        if k:
            f = pdiv(f, g, p)
            h = pmod(h, f, p)
    return tuple(sorted(degs, reverse=True))


def primes_upto(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1)
    s[:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i in range(n + 1) if s[i]]


def entropy(xs: Sequence[Hashable]) -> float:
    n = len(xs)
    return -sum(c / n * math.log2(c / n) for c in Counter(xs).values())


def empirical_channel(f: Poly, residue: Callable[[int], Hashable], bad: int, X: int) -> Tuple[int, float]:
    rows = [(residue(p), splitting_type(f, p)) for p in primes_upto(X) if bad % p]
    r = [a for a, _ in rows]
    t = [b for _, b in rows]
    return len(rows), entropy(r) + entropy(t) - entropy(rows)


if __name__ == "__main__":
    n, I = empirical_channel([-2, 0, 0, 0, 0, 0, 1], lambda p: p % 24, 6, 60000)
    print(f"x^6-2 over {n} primes: empirical I(p mod 24 ; type) = {I:.4f}; "
          f"group value 4/3 + log2(3)/4 = {4/3 + math.log2(3)/4:.4f}")

