"""The type-channel landscape: channel, type entropy, ceiling and sandwich for twelve Galois groups."""
from __future__ import annotations

import math
from collections import Counter
from typing import Callable, Dict, List, Sequence, Tuple

import matplotlib.pyplot as plt

Perm = Tuple[int, ...]


def compose(a: Perm, b: Perm) -> Perm:
    return tuple(a[b[x]] for x in range(len(a)))


def inverse(a: Perm) -> Perm:
    r = [0] * len(a)
    for i, v in enumerate(a):
        r[v] = i
    return tuple(r)


def generate(gens: Sequence[Perm]) -> List[Perm]:
    ident: Perm = tuple(range(len(gens[0])))
    seen, frontier = {ident}, [ident]
    while frontier:
        nxt = []
        for g in frontier:
            for s in gens:
                h = compose(s, g)
                if h not in seen:
                    seen.add(h)
                    nxt.append(h)
        frontier = nxt
    return sorted(seen)


def affine(n: int, units: Sequence[int]) -> List[Perm]:
    return generate([tuple((u * k + a) % n for k in range(n)) for u in units for a in range(n)])


def cycle_type(g: Perm) -> Tuple[int, ...]:
    seen, out = set(), []
    for x in range(len(g)):
        if x not in seen:
            m, y = 0, x
            while y not in seen:
                seen.add(y); y = g[y]; m += 1
            out.append(m)
    return tuple(sorted(out, reverse=True))


def H(xs: Sequence) -> float:
    n = len(xs)
    return -sum(c / n * math.log2(c / n) for c in Counter(xs).values())


def report(G: List[Perm]) -> Dict[str, float]:
    comm = {compose(compose(a, b), compose(inverse(a), inverse(b))) for a in G for b in G}
    N = generate(sorted(comm))
    lab: Dict[Perm, int] = {}
    k = 0
    for g in G:
        if g not in lab:
            for h in N:
                lab[compose(g, h)] = k
            k += 1
    c = [lab[g] for g in G]
    T = [cycle_type(g) for g in G]
    HT = H(T)
    I = H(c) + HT - H(list(zip(c, T)))
    return {"H": HT, "I": I, "cap": math.log2(k),
            "lo": max(0.0, HT - math.log2(len(N))), "hi": min(HT, math.log2(k))}


s = lambda *p: tuple(p)
GROUPS: Dict[str, List[Perm]] = {
    "C4": generate([s(1, 2, 3, 0)]), "V4": generate([s(1, 0, 3, 2), s(2, 3, 0, 1)]),
    "S3": generate([s(1, 0, 2), s(1, 2, 0)]), "D4": affine(4, [1, 3]),
    "A4": generate([s(1, 2, 0, 3), s(1, 0, 3, 2)]), "S4": generate([s(1, 0, 2, 3), s(1, 2, 3, 0)]),
    "D5": affine(5, [1, 4]), "F20": affine(5, [1, 2, 3, 4]),
    "A5": generate([s(1, 2, 0, 3, 4), s(0, 1, 3, 4, 2), s(1, 2, 3, 4, 0)]),
    "S5": generate([s(1, 0, 2, 3, 4), s(1, 2, 3, 4, 0)]), "D6": affine(6, [1, 5]),
    "S3 reg": generate([s(2, 3, 4, 5, 0, 1), s(1, 0, 5, 4, 3, 2)]),
}

names = list(GROUPS)
R = [report(GROUPS[n]) for n in names]
x = range(len(names))
fig, ax = plt.subplots(figsize=(12, 5.5))
ax.bar([i - 0.27 for i in x], [r["H"] for r in R], 0.27, label="type entropy $H(T)$", color="#c792ea")
ax.bar(list(x), [r["I"] for r in R], 0.27, label="channel $I(c;T)$", color="#4c78ff")
ax.bar([i + 0.27 for i in x], [r["cap"] for r in R], 0.27, label="ceiling $\\log_2[G:G']$", color="#5ad19a")
for i, r in enumerate(R):
    ax.plot([i, i], [r["lo"], r["hi"]], color="black", lw=2)
    ax.plot([i - 0.1, i + 0.1], [r["lo"]] * 2, color="black", lw=2)
    ax.plot([i - 0.1, i + 0.1], [r["hi"]] * 2, color="black", lw=2)
ax.plot([], [], color="black", lw=2, label="sandwich $[\\max(0,H(T)-\\log_2|G'|),\\ \\min(H(T),\\log_2[G:G'])]$")
ax.set_xticks(list(x)); ax.set_xticklabels(names)
ax.set_ylabel("bits")
ax.set_title("The type-channel law across Galois groups: abelian = full pinning, perfect = sealed")
ax.legend(loc="upper left", fontsize=9)
plt.tight_layout()
plt.savefig("type_channel_landscape.png", dpi=150)
plt.show()

"""Where the loss lives: joint (splitting type x coset) tables for D4 (x^4-2) and D6 (x^6-2)."""
from __future__ import annotations

import math
from collections import Counter
from typing import Dict, List, Sequence, Tuple

import matplotlib.pyplot as plt
import numpy as np

Perm = Tuple[int, ...]


def affine(n: int, units: Sequence[int]) -> List[Perm]:
    return sorted({tuple((u * k + a) % n for k in range(n)) for u in units for a in range(n)})


def cycle_type(g: Perm) -> str:
    seen, out = set(), []
    for x in range(len(g)):
        if x not in seen:
            m, y = 0, x
            while y not in seen:
                seen.add(y); y = g[y]; m += 1
            out.append(m)
    cnt = Counter(out)
    return " ".join(f"{k}^{v}" if v > 1 else f"{k}" for k, v in sorted(cnt.items(), reverse=True))


def dihedral_coset(g: Perm, n: int) -> str:
    """Coset of the derived subgroup (rotations by even steps) in D_n for even n."""
    rot = g[1] == (g[0] + 1) % n
    par = g[0] % 2
    return ("rot" if rot else "ref") + ("-odd" if par else "-even")


def table(n: int) -> Tuple[List[str], List[str], np.ndarray]:
    G = affine(n, [1, n - 1])
    rows = sorted({cycle_type(g) for g in G})
    cols = sorted({dihedral_coset(g, n) for g in G})
    M = np.zeros((len(rows), len(cols)))
    for g in G:
        M[rows.index(cycle_type(g)), cols.index(dihedral_coset(g, n))] += 1
    return rows, cols, M


fig, axes = plt.subplots(1, 2, figsize=(12, 4.8))
for ax, n, title in [(axes[0], 4, "$D_4$ ($x^4-2$): loss $= \\frac38 h(\\frac13) \\approx 0.344$"),
                     (axes[1], 6, "$D_6$ ($x^6-2$): loss $= \\frac13 h(\\frac14) \\approx 0.270$")]:
    rows, cols, M = table(n)
    ax.imshow(M, cmap="Blues")
    for i in range(len(rows)):
        for j in range(len(cols)):
            if M[i, j]:
                ax.text(j, i, int(M[i, j]), ha="center", va="center", fontsize=13)
        if (M[i] > 0).sum() > 1:
            ax.add_patch(plt.Rectangle((-0.5, i - 0.5), len(cols), 1, fill=False, ec="red", lw=2.5))
    ax.set_xticks(range(len(cols))); ax.set_xticklabels(cols)
    ax.set_yticks(range(len(rows))); ax.set_yticklabels(rows)
    ax.set_xlabel("coset of the derived subgroup"); ax.set_ylabel("splitting type")
    ax.set_title(title)
plt.suptitle("Red rows: splitting types that straddle two cosets - the only source of loss")
plt.tight_layout()
plt.savefig("where_the_loss_lives.png", dpi=150)
plt.show()
